//! %TypedArray%.prototype.reduceRight ( _callback_ [ , _initialValue_ ] )
//!
//! Spec: https://tc39.es/ecma262/#sec-%typedarray%.prototype.reduceright

use kahvi_core::object::typed_array::typed_array_length;
use kahvi_core::prelude::*;

use crate::support::typed_array::{typed_array_get_element, validate_typed_array};

/// TypedArray.prototype.reduceRight
pub(crate) fn prototype_reduce_right(
    agent: &mut Agent,
    this: Value,
    args: &[Value],
    _new_target: Option<Object>,
) -> JsResult<Value> {
    // The interpretation and use of the arguments of this method are the same as for `Array.prototype.reduceRight` as defined in [sec-array.prototype.reduceright].
    // This method performs the following steps when called:
    //
    // 1. Let _obj_ be the *this* value.
    let obj = this;
    // 2. Let _taRecord_ be ? ValidateTypedArray(_obj_, ~seq-cst~).
    let ta_record = validate_typed_array(agent, obj)?;
    let Value::Object(obj) = obj else {
        return Err(agent.throw_type_error("not a TypedArray"));
    };
    // 3. Let _length_ be TypedArrayLength(_taRecord_).
    let length = typed_array_length(agent, ta_record);
    // 4. If IsCallable(_callback_) is *false*, throw a *TypeError* exception.
    let callback = args.get_or_undefined(0);
    if !ops::is_callable(agent, callback) {
        return Err(
            agent.throw_type_error("TypedArray.prototype.reduceRight callback is not a function")
        );
    }
    let initial_value = args.get(1).copied();
    // 5. If _length_ = 0 and _initialValue_ is not present, throw a *TypeError* exception.
    if length == 0 && initial_value.is_none() {
        return Err(agent.throw_type_error("Reduce of empty array with no initial value"));
    }
    // The callback may collect garbage: obj, callback and the accumulator stay rooted.
    agent.with_roots(
        &[
            Value::Object(obj),
            callback,
            initial_value.unwrap_or(Value::Undefined),
        ],
        |agent| {
            // 6. Let _k_ be _length_ - 1.
            let mut k: i64 = length as i64 - 1;
            // 7. Let _accumulator_ be *undefined*.
            let mut accumulator = Value::Undefined;
            // 8. If _initialValue_ is present, then
            if let Some(initial_value) = initial_value {
                // a. Set _accumulator_ to _initialValue_.
                accumulator = initial_value;
            } else {
                // 9. Else,
                // a. Set _accumulator_ to TypedArrayGetElement(_obj_, 𝔽(_k_)).
                accumulator = typed_array_get_element(agent, obj, k as f64);
                // b. Set _k_ to _k_ - 1.
                k -= 1;
            }
            // 10. Repeat, while _k_ ≥ 0,
            while k >= 0 {
                // a. Let _kValue_ be TypedArrayGetElement(_obj_, 𝔽(_k_)).
                let k_value = typed_array_get_element(agent, obj, k as f64);
                let mark = agent.push_root(k_value);
                agent.push_root(accumulator);
                // b. Set _accumulator_ to ? Call(_callback_, *undefined*, « _accumulator_, _kValue_, 𝔽(_k_), _obj_ »).
                accumulator = ops::call_rooted(
                    agent,
                    callback,
                    Value::Undefined,
                    &[accumulator, k_value, Value::Number(k as f64), Value::Object(obj)],
                )?;
                agent.pop_roots(mark);
                agent.push_root(accumulator);
                // c. Set _k_ to _k_ - 1.
                k -= 1;
            }
            // 11. Return _accumulator_.
            Ok(accumulator)
        },
    )
}
EOF
